import React from 'react';
import {
    Box,
    Typography,
    FormControlLabel,
    Checkbox,
    Select,
    MenuItem,
    FormControl,
    InputLabel
} from '@mui/material';
import type { ElementPropertyPanelProps } from './FrameEngine2_ElementProperties_Types';
import {
    TextInput,
    ColorInput,
    usePropertiesUpdate
} from './FrameEngine2_ElementProperties_Shared';

/**
 * Properties panel for Tunnel elements
 */
export const TunnelProperties: React.FC<ElementPropertyPanelProps> = ({
    selectedElement,
    onUpdateElement
}) => {
    // Hook must be called before any conditional returns
    const updateProperty = usePropertiesUpdate(selectedElement, onUpdateElement);

    // Type guard: This component is only rendered for tunnel elements
    if (selectedElement.type !== 'tunnel') {
        return null;
    }

    return (
        <Box>
            <Typography variant="subtitle2" fontWeight="bold" mb={1}>
                Tunnel Properties
            </Typography>

            {/* Basic Properties */}
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5} mt={1}>
                BASIC
            </Typography>

            <ColorInput
                label="Primary Color"
                value={selectedElement.properties.primaryColor || '#ff00ff'}
                onChange={(v) => updateProperty('primaryColor', v)}
            />

            <ColorInput
                label="Secondary Color"
                value={selectedElement.properties.secondaryColor || '#00ffff'}
                onChange={(v) => updateProperty('secondaryColor', v)}
            />

            <ColorInput
                label="Background Color"
                value={selectedElement.properties.backgroundColor || '#000000'}
                onChange={(v) => updateProperty('backgroundColor', v)}
            />

            <FormControl fullWidth size="small" sx={{ mb: 1 }}>
                <InputLabel>Tunnel Type</InputLabel>
                <Select
                    value={selectedElement.properties.tunnelType || 'circular'}
                    label="Tunnel Type"
                    onChange={(e) => updateProperty('tunnelType', e.target.value)}
                >
                    <MenuItem value="circular">Circular</MenuItem>
                    <MenuItem value="square">Square</MenuItem>
                    <MenuItem value="hexagon">Hexagon</MenuItem>
                    <MenuItem value="star">Star</MenuItem>
                    <MenuItem value="spiral">Spiral</MenuItem>
                </Select>
            </FormControl>

            {/* Motion Properties */}
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5} mt={1.5}>
                MOTION
            </Typography>

            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1 }}>
                <TextInput
                    label="Speed"
                    type="number"
                    step={0.01}
                    value={selectedElement.properties.speed ?? 1}
                    onChange={(v) => updateProperty('speed', parseFloat(v as string) || 0)}
                    helperText="0.01-10 (use decimals)"
                />
                <TextInput
                    label="Rotation"
                    type="number"
                    step={0.1}
                    value={selectedElement.properties.rotation ?? 0.5}
                    onChange={(v) => updateProperty('rotation', parseFloat(v as string) || 0)}
                    helperText="-5 to 5"
                />
            </Box>

            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1 }}>
                <TextInput
                    label="Depth"
                    type="number"
                    value={selectedElement.properties.depth ?? 20}
                    onChange={(v) => updateProperty('depth', parseFloat(v as string) || 20)}
                />
                <TextInput
                    label="Ring Spacing"
                    type="number"
                    value={selectedElement.properties.ringSpacing ?? 5}
                    onChange={(v) => updateProperty('ringSpacing', parseFloat(v as string) || 5)}
                />
            </Box>

            <TextInput
                label="Twist"
                type="number"
                value={selectedElement.properties.twist ?? 0}
                onChange={(v) => updateProperty('twist', parseFloat(v as string) || 0)}
                helperText="0-10 twist amount"
            />

            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1 }}>
                <TextInput
                    label="Pulse Speed"
                    type="number"
                    step={0.1}
                    value={selectedElement.properties.pulseSpeed ?? 1}
                    onChange={(v) => updateProperty('pulseSpeed', parseFloat(v as string) || 0)}
                    helperText="0-5"
                />
                <TextInput
                    label="Pulse Amount"
                    type="number"
                    step={0.01}
                    value={selectedElement.properties.pulseAmount ?? 0.2}
                    onChange={(v) => updateProperty('pulseAmount', parseFloat(v as string) || 0)}
                    helperText="0-1"
                />
            </Box>

            {/* 3D Curve Properties */}
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5} mt={1.5}>
                3D CURVE
            </Typography>

            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1 }}>
                <TextInput
                    label="Curve Target X"
                    type="number"
                    step={0.1}
                    value={selectedElement.properties.curveTargetX ?? 0}
                    onChange={(v) => updateProperty('curveTargetX', parseFloat(v as string) || 0)}
                    helperText="-1 to 1"
                />
                <TextInput
                    label="Curve Target Y"
                    type="number"
                    step={0.1}
                    value={selectedElement.properties.curveTargetY ?? 0}
                    onChange={(v) => updateProperty('curveTargetY', parseFloat(v as string) || 0)}
                    helperText="-1 to 1"
                />
            </Box>

            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1 }}>
                <TextInput
                    label="Curve Strength"
                    type="number"
                    step={0.1}
                    value={selectedElement.properties.curveStrength ?? 1}
                    onChange={(v) => updateProperty('curveStrength', parseFloat(v as string) || 0)}
                    helperText="0-2"
                />
                <TextInput
                    label="Banking"
                    type="number"
                    step={0.1}
                    value={selectedElement.properties.banking ?? 0.5}
                    onChange={(v) => updateProperty('banking', parseFloat(v as string) || 0)}
                    helperText="0-1"
                />
            </Box>

            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1 }}>
                <TextInput
                    label="Pitch"
                    type="number"
                    step={0.1}
                    value={selectedElement.properties.pitch ?? 0}
                    onChange={(v) => updateProperty('pitch', parseFloat(v as string) || 0)}
                    helperText="-1 to 1"
                />
                <TextInput
                    label="Perspective"
                    type="number"
                    step={0.1}
                    value={selectedElement.properties.perspective ?? 1}
                    onChange={(v) => updateProperty('perspective', parseFloat(v as string) || 0)}
                    helperText="0.5-2"
                />
            </Box>

            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1 }}>
                <TextInput
                    label="Origin X"
                    type="number"
                    step={0.1}
                    value={selectedElement.properties.originX ?? 0.5}
                    onChange={(v) => updateProperty('originX', parseFloat(v as string) || 0)}
                    helperText="0-1"
                />
                <TextInput
                    label="Origin Y"
                    type="number"
                    step={0.1}
                    value={selectedElement.properties.originY ?? 0.5}
                    onChange={(v) => updateProperty('originY', parseFloat(v as string) || 0)}
                    helperText="0-1"
                />
            </Box>

            {/* Effects Properties */}
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5} mt={1.5}>
                EFFECTS
            </Typography>

            <TextInput
                label="Line Width"
                type="number"
                step={0.5}
                value={selectedElement.properties.lineWidth ?? 2}
                onChange={(v) => updateProperty('lineWidth', parseFloat(v as string) || 0)}
                helperText="1-10 line thickness"
            />

            <FormControlLabel
                control={
                    <Checkbox
                        checked={selectedElement.properties.glow !== false}
                        onChange={(e) => updateProperty('glow', e.target.checked)}
                    />
                }
                label="Glow Effect"
            />

            {selectedElement.properties.glow !== false && (
                <TextInput
                    label="Glow Intensity"
                    type="number"
                    step={0.5}
                    value={selectedElement.properties.glowIntensity ?? 10}
                    onChange={(v) => updateProperty('glowIntensity', parseFloat(v as string) || 0)}
                    helperText="0-20"
                />
            )}

            <FormControlLabel
                control={
                    <Checkbox
                        checked={selectedElement.properties.scanlines !== false}
                        onChange={(e) => updateProperty('scanlines', e.target.checked)}
                    />
                }
                label="Scanlines"
            />

            {selectedElement.properties.scanlines !== false && (
                <TextInput
                    label="Scanline Intensity"
                    type="number"
                    step={0.01}
                    value={selectedElement.properties.scanlineIntensity ?? 0.3}
                    onChange={(v) => updateProperty('scanlineIntensity', parseFloat(v as string) || 0)}
                    helperText="0-1"
                />
            )}

            <FormControlLabel
                control={
                    <Checkbox
                        checked={selectedElement.properties.chromatic === true}
                        onChange={(e) => updateProperty('chromatic', e.target.checked)}
                    />
                }
                label="Chromatic Aberration"
            />

            {selectedElement.properties.chromatic === true && (
                <TextInput
                    label="Chromatic Amount"
                    type="number"
                    step={0.5}
                    value={selectedElement.properties.chromaticAmount ?? 2}
                    onChange={(v) => updateProperty('chromaticAmount', parseFloat(v as string) || 0)}
                    helperText="0-10"
                />
            )}

            <FormControlLabel
                control={
                    <Checkbox
                        checked={selectedElement.properties.pixelate === true}
                        onChange={(e) => updateProperty('pixelate', e.target.checked)}
                    />
                }
                label="Pixelate"
            />

            {selectedElement.properties.pixelate === true && (
                <TextInput
                    label="Pixel Size"
                    type="number"
                    step={1}
                    value={selectedElement.properties.pixelSize ?? 4}
                    onChange={(v) => updateProperty('pixelSize', parseFloat(v as string) || 0)}
                    helperText="1-20"
                />
            )}

            <FormControlLabel
                control={
                    <Checkbox
                        checked={selectedElement.properties.colorCycle === true}
                        onChange={(e) => updateProperty('colorCycle', e.target.checked)}
                    />
                }
                label="Color Cycle"
            />

            {selectedElement.properties.colorCycle === true && (
                <TextInput
                    label="Color Cycle Speed"
                    type="number"
                    step={0.001}
                    value={selectedElement.properties.colorCycleSpeed ?? 0.01}
                    onChange={(v) => updateProperty('colorCycleSpeed', parseFloat(v as string) || 0)}
                    helperText="0.001-0.1"
                />
            )}

            {/* Depth Fade Properties */}
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5} mt={1.5}>
                DEPTH FADE
            </Typography>

            <FormControlLabel
                control={
                    <Checkbox
                        checked={selectedElement.properties.depthFade === true}
                        onChange={(e) => updateProperty('depthFade', e.target.checked)}
                    />
                }
                label="Enable Depth Fade"
            />

            {selectedElement.properties.depthFade === true && (
                <FormControl fullWidth size="small" sx={{ mb: 1 }}>
                    <InputLabel>Fade End</InputLabel>
                    <Select
                        value={selectedElement.properties.fadeEnd || 'back'}
                        label="Fade End"
                        onChange={(e) => updateProperty('fadeEnd', e.target.value)}
                    >
                        <MenuItem value="front">Front</MenuItem>
                        <MenuItem value="back">Back</MenuItem>
                    </Select>
                </FormControl>
            )}
        </Box>
    );
};

export default TunnelProperties;
